<?php
require dirname(__DIR__).'/includes/bootstrap.php';$admin=require_admin();$errors=[];$roles=['utilisateur','limite','admin'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['user_id']??0);$role=(string)($_POST['role']??'');if($id===(int)$admin['id'])$errors[]='Tu ne peux pas modifier ton propre grade depuis cette page.';elseif(!in_array($role,$roles,true))$errors[]='Grade invalide.';else{$s=$pdo->prepare('SELECT id FROM users WHERE id=:id');$s->execute(['id'=>$id]);if(!$s->fetch())$errors[]='Utilisateur introuvable.';else{$pdo->prepare('UPDATE users SET role=:r WHERE id=:id')->execute(['r'=>$role,'id'=>$id]);flash('Grade utilisateur modifié.','success');redirect('admin/users.php');}}}
$users=$pdo->query('SELECT id,username,email,role,created_at FROM users ORDER BY id ASC')->fetchAll();$pageTitle='Gestion des membres';require dirname(__DIR__).'/includes/header.php';?>
<section class="panel"><h1>Gestion des membres</h1><div class="admin-nav"><a class="btn" href="<?=e(url('admin/games.php'))?>">Administration des jeux</a><a class="btn" href="<?=e(url('index.php'))?>">Voir le site</a></div><?php foreach($errors as $err): ?><div class="flash error"><?=e($err)?></div><?php endforeach; ?><p><strong>Utilisateur :</strong> peut participer aux fonctions communautaires.<br><strong>Limité :</strong> peut consulter le site, mais ne peut pas poster/commenter/noter (la modération des interactions sera à appliquer aux modules communautaires futurs).<br><strong>Admin :</strong> accès à l’administration et gestion des grades.</p><div class="table-wrap"><table><thead><tr><th>ID</th><th>Pseudo</th><th>E-mail</th><th>Grade</th><th>Inscrit le</th><th>Action</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><?=(int)$u['id']?></td><td><?=e($u['username'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td><td><?=e($u['created_at'])?></td><td><?php if((int)$u['id']!==(int)$admin['id']): ?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="user_id" value="<?=(int)$u['id']?>"><select name="role" aria-label="Grade de <?=e($u['username'])?>"><?php foreach($roles as $r): ?><option value="<?=e($r)?>" <?=$u['role']===$r?'selected':''?>><?=e($r)?></option><?php endforeach; ?></select> <button class="btn" type="submit">Modifier</button></form><?php else: ?>Compte connecté<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
